// CSD_RATIONALE_BEGIN
// This strategy tracks the visible output (`generated`), whether decoding is
// currently inside the SQL constrained span, the active constrained SQL prefix
// (`currentConstrainedOut`), and a simple step counter (`steps`). Outside the
// span it uses short unconstrained chunks so the model can naturally emit the
// visible opening delimiter `"<<";` if that delimiter is already present we
// enter constrained mode without appending it again.
// Inside the span, the strategy chooses between single-token hard constrained
// decoding and bounded multi-token symbol decoding based on parser narrowness.
// When the parser state is narrow, it uses AdaptiveConstrainedStep to keep hard
// validity while softly preferring caller-supplied token groups. When the state
// is broader, it uses ConstrainedSymbolInGenerated with the provided
// `stepTokenBudget` to accept the longest valid prefix from a short rollout.
// As soon as the parser reports a complete SQL query, the strategy closes the
// visible span with `">>"`. This tracked state ensures that active constrained
// content always remains a parser-valid SQL prefix while visible growth stays
// within the consumed token budget.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: In the outside-span chunk branch, `insideConstrainedOut`
//   stays false unless `UnconstrainedChunk` stops on the observed open-span
//   token; then `EnterObservedConstrainedSpan` sets `currentConstrainedOut := []`,
//   which is valid by the method precondition `parser.IsValidPrefix([])`.
//   In the close branch, `CloseConstrainedSpan` exits constrained mode, so the
//   implication becomes vacuous. In the narrow constrained branch,
//   `AdaptiveConstrainedStep` returns either EOS or a parser-valid next token;
//   on non-EOS we commit it with `AppendConstrainedToken`, preserving validity.
//   In the symbol branch, `ConstrainedSymbolInGenerated` returns a constrained
//   prefix accepted by the parser, so `currentConstrainedOut` remains valid.
// progress: In the outside-span chunk branch, `steps` increases by `stepsUsed`
//   from `UnconstrainedChunk`, and visible output grows by at most that many
//   tokens because EOS is counted in `stepsUsed` but not appended. The
//   `EnterObservedConstrainedSpan` bookkeeping consumes no extra budget and
//   does not change `generated`. In the close branch, `CloseConstrainedSpan`
//   consumes one token-step and appends at most one visible delimiter, so the
//   bound is preserved. In the narrow branch, `AdaptiveConstrainedStep`
//   consumes one token-step and `AppendConstrainedToken` appends at most one
//   visible token. In the symbol branch, `ConstrainedSymbolInGenerated`
//   consumes `stepsUsed`; even if some sampled tokens are rejected or EOS is
//   hit, visible growth is at most `stepsUsed`, so
//   `|generated| <= |generatedPrefix| + steps` is preserved.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var narrowThreshold: nat := 12;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var chunkBudget: nat := maxSteps - steps;
    var chunkedGenerated, stoppedOnOpenSpan, stoppedOnEos, stepsUsed := helpers.UnconstrainedChunk(
      lm, prompt, generated, chunkBudget, "<<", eosToken
    );
    generated := chunkedGenerated;
    steps := steps + stepsUsed;
    if stoppedOnEos {
      break;
    } else if stoppedOnOpenSpan {
      var enteredGenerated, enteredInside, enteredCurrent := helpers.EnterObservedConstrainedSpan(lm, generated);
      generated := enteredGenerated;
      insideConstrainedOut := enteredInside;
      currentConstrainedOut := enteredCurrent;
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else {
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    var constrainedPrompt := prompt + stablePrefix;
    var validCount := helpers.ValidTokenCount(parser, currentConstrainedOut);
    if validCount <= narrowThreshold || stepTokenBudget <= 1 {
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, narrowThreshold, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := appendedGenerated;
        insideConstrainedOut := appendedInside;
        currentConstrainedOut := appendedCurrent;
      }
    } else {
      var remaining: nat := maxSteps - steps;
      var symbolBudget: nat := if stepTokenBudget > remaining then remaining else stepTokenBudget;
      var symbolGenerated, symbolCurrent, hitEos, symbolSteps := helpers.ConstrainedSymbolInGenerated(
        lm, parser, constrainedPrompt, generated, currentConstrainedOut, symbolBudget, eosToken
      );
      generated := symbolGenerated;
      currentConstrainedOut := symbolCurrent;
      steps := steps + symbolSteps;
      if hitEos {
        break;
      }
    }
  }
}

cost := steps;

